import { Group } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const node = new Group();

  // Load GLB mesh
  const glbPromise = ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    node.add(gltf.scene);
    // Store reference for potential disposal
    node.userData._gltf = gltf;
  });

  // Timelines for interactions
  let hoverTl = null;
  let pressTl = null;
  let isHover = false;

  // Hover handler (rise‑in 0.15 units)
  function onHover() {
    if (isHover) return;
    isHover = true;
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(node.position, {
      y: node.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  // Unhover handler (revert)
  function onUnhover() {
    if (!isHover) return;
    isHover = false;
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(node.position, {
      y: node.position.y - 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  }

  // Click handler (press‑down + emit event)
  function onClick() {
    pressTl?.kill();
    pressTl = gsap.timeline();
    pressTl
      .to(node.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      })
      .to(node.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
    ctx.emit('hub-home.select');
  }

  // Attach handlers to userData
  node.userData.handlers = {
    hover: onHover,
    unhover: onUnhover,
    click: onClick,
  };

  // Cleanup routine
  node.userData.cleanup = () => {
    hoverTl?.kill();
    pressTl?.kill();
    // Dispose GLTF scene if present
    const gltf = node.userData._gltf;
    if (gltf && gltf.scene) {
      gltf.scene.traverse((obj) => {
        if (obj.isMesh && obj.geometry) obj.geometry.dispose();
        if (obj.isMesh && obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      });
    }
    node.clear();
  };

  // Apply any cinematic primitives listed in config (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const prim = ctx.primitives[p.name];
      if (prim) {
        const result = prim(node, p.params);
        // Store for cleanup
        if (!node.userData._primitives) node.userData._primitives = [];
        node.userData._primitives.push(result);
      }
    });
  }

  // Ensure cleanup also disposes primitives
  const origCleanup = node.userData.cleanup;
  node.userData.cleanup = () => {
    if (node.userData._primitives) {
      node.userData._primitives.forEach((r) => {
        if (r.cleanup) r.cleanup();
      });
    }
    origCleanup();
  };

  return node;
}
